INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ise321', 'stk-bader_alqahtani', 'ISE 321', 'doc', '{"docs": [{"id": "stk-dr-f180888", "n": "Dr. Mohammad Abdel-Aal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE321-211\nالتحضير :\nيحضر برابط في اخر نص ساعة من المحاضرة\nطريقة الشرح :\nيشرح من السلايدات و يتجاوب مع الاسئلة ما كنت اركز معه لكن اتوقع شرحه كويس لكنه ما يعطي كل شي حقه كان يحاول يمشي بسرعة فصرت اذاكر من المقاطع\nالكويزات :\nكوزاته على شرحه مو صعبة اذا مذاكر و حال الاقزامبل حق السلايدات بتحلها مرات يجيب شغلات مالها داعي مو على شرحه بس يحط درجات قليل عليها و يحب يجيب كونسبت يعني لا تتوقع الكوز كله حل بيجيب لك فقرة فقرتين اشرح و عدد\nالمد:كومون و كان متوسط افرجه كان ٦٠٪؜ تقريبا حق سكشنا\nالفاينلات :كان اسهل من المد\nالقريد النهائي:C\nالصوت:واضح\nإضافات :الدكتور يحب يجيب اسالة كونسبت بس واضحة اذا كنت حافظ طريقة الحل بتحفر فيها بس لو فاهم بتجاوبها بسلاسة عموم الدكتور اخلاقة حلوه بس يعيبه تصحيحه سيء جدا ي ابيض ي اسود", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533370-ise321", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abdel-aal/180888/4", "user": "Bader_Alqahtani", "ts": 1641681843000, "tid": 180888, "pn": 4}}]}', 1641681843000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-ise321', 'stk-user12137', 'ISE 321', 'doc', '{"docs": [{"id": "stk-dr-f185225", "n": "Dr. Ahmad Baubaid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ISE321- Term232\nالتحضير:\nنص الأيام يحضر والنص الثاني ما يحضر, واذا حضر فبيكون عبر الباركود تقريبا في نص المحاضرة او نهايتها, ما يهتم بالتأخير الا تقريبا (15-20) دقيقة ولو تدخل بعدها يقولك لا تصور الباركود, وكان عندنا 8 غيابات مجانية\n\nطريقة الشرح:\nشرييييييح أفضل شرح بتشوفه بحياتك ما شاء الله\nأسلوب شرحه غريب شوي, كأنه يبغاك تتفكر معاه وتكتشف كيف تتوصل لهذي النظرية او تلك الفكرة او ذاك الحل بدون ما يعطيك اياها بشكل مباشر, عشان تفهم عدل عدل\nوسلايداته الي يشرح بها ممتازة جدا ومريح استعمالها\nأمثلته ممتازة وعصرية, مثل: العاب الRPG, ال ZIGZAG, لعبة الحلقات الي تنفخها عشان تدخلها داخل العمودين, وغيرهم…\nويجاوب على أي سؤال يطرح مهما كان غبي أو تافه\n\nالكويزات:\nالشباب خوفوني من كويزاته في البداية لكنها طلعت مو صعبة ولا سهلة يعني وسط … والاسئلة ذكية ما فيها شيء تقدر تنقد عليها فيه … يشيل اسوء كويز\n\nالميد:\nكومن …الميد (كاملا كله على التشابتر الاول الIP)وهو الاصعب والافرج الظاهر 19 كان وانا جبت فوق الأفرج شوي 22.5 من 30\n\nالفاينل:\n\nالقريد النهائي:\nA+++\n\nالصوت:\nواضح جدا وعالي, ولهجته تحسه أمريكي من كثر ما هي مضبوطة\n\nإضافات:\n-مشكلة الدكتور أنه متحجر شوي في تغيير مواعيد الكويزات والشغلات هذي, يعني ما هو فلكسبل\n-الدكتور أشوفه خيار ممتاز للمادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537310-ise321", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-baubaid/185225/2", "user": "user12137", "ts": 1715174179000, "tid": 185225, "pn": 2}}]}', 1715174179000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
